  let best = null;
  let bestD = maxDist;
  for (const car of [...G.traffic, ...G.parked]) {
    if (car.driven) continue;
    const d = Math.hypot(car.pos.x - G.player.pos.x, car.pos.z - G.player.pos.z);
    if (d < bestD) {
      bestD = d;
      best = car;
    }
  }
  return best;
}
